@Command([EditDocument];"1");

@If (Site= ""; @Return(@Do(@Command([EditGotoField];"Site") ;@Prompt([Ok];"Missing Value"; "Please select the Site!")));"");
@If (TeamMembers= ""; @Return(@Do(@Command([EditGotoField];"TeamMembers") ;@Prompt([Ok];"Missing Value"; "Please select the Team Members before proceeding!")));"");
@If (InsDate= ""; @Return(@Do(@Command([EditGotoField];"InsDate") ;@Prompt([Ok];"Missing Value"; "Please state the date of Inspection before proceeding!")));"");
@If (InsTime= ""; @Return(@Do(@Command([EditGotoField];"InsTime") ;@Prompt([Ok];"Missing Value"; "Please state the time of Inspection before proceeding!")));"");

FIELD SubmittedBy := @V3UserName;
FIELD SubmittedDate :=@Today;
FIELD CurrentAction :="Submitted";

@Command([FileSave]);

@MailSend(TeamMembers;NULL;NULL;"Cafeteria Inspection - Submitted for Review : "  +  INO ;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

